  const applyView=()=>{$('#stage-transform').setAttribute('transform',stageTransform(project,pan,zoom,mirror));const label=$('.zoom-label');if(label)label.textContent=`${Math.round(zoom*100)}%`;};
  const zoomAt=(event,newZoom)=>{const anchor=new DOMPoint(event.clientX,event.clientY).matrixTransform($('#stage-transform').getScreenCTM().inverse()),mid=rootPoint(event),cx=project.stage.width*30,cy=project.stage.depth*30;zoom=clamp(newZoom,.25,6);pan={x:mid.x-cx-zoom*(mirror?-1:1)*(anchor.x-cx),y:mid.y-cy-zoom*(anchor.y-cy)};applyView();};
