    if(Math.hypot(e.clientX-drag.screen.x,e.clientY-drag.screen.y)<3&&!drag.saved)return;if(!drag.saved){remember();drag.saved=true;}
    let dx=p.x-drag.start.x,dz=p.z-drag.start.z;if(snap){dx=Math.round(dx*2)/2;dz=Math.round(dz*2)/2;}
    if(drag.type==='object'){const prop=project.props.find(v=>v.id===drag.original.id);prop.x=shortNum(clamp(drag.original.x+dx,-100,100));prop.z=shortNum(clamp(drag.original.z+dz,-100,100));$(`[data-stage-object="${prop.id}"]`)?.setAttribute('transform',`translate(${(prop.x-drag.original.x)*60} ${-(prop.z-drag.original.z)*60})`);return;}
    form().positions=translateSelection(drag.positions,selected,dx,dz,project.stage);form().positions.filter(p=>selected.has(p.performerId)).forEach(p=>$(`[data-marker="${p.performerId}"]`)?.setAttribute('transform',`translate(${stagePoint(project,p).x} ${stagePoint(project,p).y})`));
