  const cancel=e=>{pointers.delete(e.pointerId);gesture=null;if(drag){rollback();drag=null;render();}};svg.addEventListener('pointercancel',cancel);svg.addEventListener('lostpointercapture',e=>{if(drag)cancel(e);});
