document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){$('#stage-svg')?.dispatchEvent(new Event('cancel-stage-gesture'));selected.clear();refreshSelection();return;}
  if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#dialog').open)return;
  const mod=e.ctrlKey||e.metaKey;
  if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}
  if(mod&&['c','v'].includes(e.key.toLowerCase())&&document.activeElement?.closest('#stage-svg')){e.preventDefault();$(`[data-action="${e.key.toLowerCase()==='c'?'copy-positions':'paste-positions'}"]`)?.click();return;}
  if(mod&&e.key==='0'){e.preventDefault();zoom=1;pan={x:0,y:0};render();return;}
  if(mod&&['+','=','-'].includes(e.key)){e.preventDefault();zoom=clamp(zoom*(e.key==='-'?1/1.2:1.2),.25,6);render();return;}
  if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();selected=new Set(project.performers.map(p=>p.id));refreshSelection();return;}
  if(e.key===' '){e.preventDefault();if(!e.repeat&&!spaceHeld){spaceHeld=true;spacePanUsed=false;}return;}
  if(e.key==='?'){helpDialog();return;}
  if(['v','h','p','m'].includes(e.key.toLowerCase())){tool={v:'cursor',h:'hand',p:'path',m:'ruler'}[e.key.toLowerCase()];if(tool==='path')showPaths=true;render();return;}
  if(e.key==='Delete'||e.key==='Backspace'){if(selected.size){e.preventDefault();removePerformers();}return;}
  if(e.key.startsWith('Arrow')&&selected.size&&!isLocked()&&!playing){e.preventDefault();remember();const step=e.shiftKey?.5:.1;const dx=e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0;const dz=e.key==='ArrowUp'?step:e.key==='ArrowDown'?-step:0;form().positions=translateSelection(form().positions,selected,dx,dz,project.stage);save();refreshStage();refreshInspector();const id=[...selected][0];$(`[data-marker="${id}"]`)?.focus({preventScroll:true});}
});

document.addEventListener('keyup',e=>{if(e.key===' '&&spaceHeld){e.preventDefault();const panUsed=spacePanUsed;spaceHeld=false;spacePanUsed=false;if(!panUsed&&!$('#dialog').open){playing?pause():play();}}});
window.addEventListener('blur',()=>{spaceHeld=false;spacePanUsed=false;pointerDown=false;});

let gainNode;
function getAudioContext(){if(!audioContext){audioContext=new AudioContext();gainNode=audioContext.createGain();gainNode.gain.value=muted?0:.65;gainNode.connect(audioContext.destination);}return audioContext;}
function demoAudio(){
  const ctx=getAudioContext(),sr=ctx.sampleRate,duration=96;
  const buffer=ctx.createBuffer(1,sr*duration,sr),out=buffer.getChannelData(0);
  // Original procedural instrumental. The displayed waveform is derived from this buffer.
  const chords=[[130.81,164.81,196],[110,130.81,164.81],[87.31,110,130.81],[98,123.47,146.83]];
  for(let i=0;i<out.length;i++){
    const t=i/sr,beat=t%.5,chord=chords[Math.floor(t/8)%4];
    const fade=Math.min(1,t/3,(duration-t)/4);
    let value=Math.sin(2*Math.PI*(55*beat+55*.03*(1-Math.exp(-beat/.03))))*Math.exp(-beat*24)*.2;
    const note=chord[Math.floor(t*2)%3]*2;
    value+=(Math.sin(2*Math.PI*note*t)+.3*Math.sin(2*Math.PI*note*2*t))*Math.exp(-beat*7)*.055;
    chord.forEach(hz=>value+=Math.sin(2*Math.PI*hz*t)*(.5+.5*Math.sin(t*.35))*.025);
    out[i]=value*fade;
  }
  return buffer;
}
function computeWave(buffer){const channel=buffer.getChannelData(0);wave=Array.from({length:340},(_,i)=>{const start=Math.floor(i/340*channel.length),end=Math.floor((i+1)/340*channel.length);let peak=0;for(let j=start;j<end;j+=Math.max(1,Math.floor((end-start)/200)))peak=Math.max(peak,Math.abs(channel[j]));return Math.min(1,peak*2.5);});}
async function play(){
  try {
    const token=++playbackToken,currentProject=project.id;const ctx=getAudioContext();await ctx.resume();if(token!==playbackToken||currentProject!==project.id)return;
    if(project.audioName&&!audioBuffer){toast('This snapshot does not include uploaded audio. Upload the original file to play it.');}
    if(!audioBuffer && !project.audioName){audioBuffer=demoAudio();computeWave(audioBuffer);const lane=$('.audio-lane');if(lane){$('svg',lane).outerHTML=waveformSVG();}}
    if(time>=project.duration)time=0;
    playing=true;clockStart=performance.now();clockOffset=time;
    if(audioBuffer&&time<audioBuffer.duration){audioSource=ctx.createBufferSource();audioSource.buffer=audioBuffer;audioSource.playbackRate.value=rate;audioSource.connect(gainNode);audioStart=ctx.currentTime;audioSource.start(0,time);}
    updatePlayButton();cancelAnimationFrame(playbackFrame);playbackFrame=requestAnimationFrame(tick);
  }catch(err){playing=false;toast('Audio could not start. Try another audio format.');updatePlayButton();}
}
function clockTime(){return clockOffset+(audioSource?audioContext.currentTime-audioStart:(performance.now()-clockStart)/1000)*rate;}
function pause(){playbackToken++;cancelAnimationFrame(playbackFrame);if(playing)time=clamp(clockTime(),0,project.duration);playing=false;if(audioSource){try{audioSource.stop();}catch{}audioSource.disconnect();audioSource=null;}updatePlayButton();}
function updatePlayButton(){$$('[data-action="play"]').forEach(b=>{b.innerHTML=icon(playing?'pause':'play');b.setAttribute('aria-label',`${playing?'Pause':'Play'} (Space)`);});}
function seek(t,reset=true){pause();time=clamp(t,0,project.duration);const f=project.formations.findLast(f=>f.time<=time)||project.formations[0];if(active!==f.id){active=f.id;selected.clear();if(reset)render();}updatePlayback(true);}
function tick(now){if(!playing)return;time=clockTime();if(time>=(loop&&loopRegion?loopRegion.end:project.duration)){if(loop){pause();time=loopRegion?.start||0;play();return;}pause();time=project.duration;updatePlayback(true);return;}if(now-lastFrame>25){const current=project.formations.findLast(f=>f.time<=time)||project.formations[0];if(active!==current.id){active=current.id;selected.clear();render();}else updatePlayback(true);lastFrame=now;}playbackFrame=requestAnimationFrame(tick);}
function updatePlayback(sample=false){
  stage3D?.update(project,samplePerformance(project,time));
  const tc=$('#transport-time');if(tc)tc.innerHTML=`${timecode(time)}<small>.${String(Math.floor(time%1*100)).padStart(2,'0')}</small><span>/ ${timecode(project.duration)}</span>`;
  const ph=$('#playhead');if(ph)ph.style.left=`${time/project.duration*100}%`;
  const beat=beatAt(project,time);const bc=$('#beat-counter');if(bc)bc.innerHTML=`${beat.phrase}<span>.</span>${beat.beat}<small>/ 8</small>`;
  if(sample||playing){samplePerformance(project,time).forEach(p=>{const el=$(`[data-marker="${p.performerId}"]`);if(el){el.setAttribute('transform',`translate(${stagePoint(project,p).x} ${stagePoint(project,p).y})`);el.querySelector('g')?.setAttribute('transform',`rotate(${p.facing})`);}});}
  $$('.timeline-formation').forEach((el,i)=>{const next=project.formations[i+1]?.time??project.duration;el.classList.toggle('playing',playing && time>=project.formations[i].time&&time<next);});
}

async function getDB(){if(audioDB)return audioDB;return new Promise((resolve,reject)=>{const req=indexedDB.open('choryn-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onsuccess=()=>{audioDB=req.result;resolve(audioDB);};req.onerror=()=>reject(req.error);});}
async function putAudio(blob,id=project.id){const db=await getDB();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function storedAudio(id){try{const db=await getDB();return await new Promise((resolve,reject)=>{const request=db.transaction('audio').objectStore('audio').get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error);});}catch{return null;}}
async function removeAudio(id){try{const db=await getDB();const tx=db.transaction('audio','readwrite');tx.objectStore('audio').delete(id);}catch{}}
let audioLoadToken=0;
async function loadAudio(){const token=++audioLoadToken,id=project.id;audioBuffer=null;persistedAudio=false;wave=[];if(!project.audioName||readOnly)return;try{const blob=await storedAudio(id);if(blob){const decoded=await getAudioContext().decodeAudioData(await blob.arrayBuffer());if(token!==audioLoadToken||project.id!==id)return;audioBuffer=decoded;computeWave(audioBuffer);persistedAudio=true;}}catch{if(project.id===id)toast('Saved music could not be loaded. Upload it again.');}}
async function switchProject(id){pause();clearTimeout(saveTimer);if(!readOnly){const index=projects.findIndex(p=>p.id===project.id);if(index>=0)projects[index]=project;try{writeCollection();}catch{toast('Could not save before switching. Export a backup.');}}project=projects.find(p=>p.id===id);readOnly=false;if(location.hash)historyReplace();active=project.formations[0].id;time=0;history=[];future=[];selected.clear();await loadAudio();render();}
function historyReplace(){window.history.replaceState(null,'',location.pathname);}
$('#audio-input').addEventListener('change',async e=>{
  const file=e.target.files[0];e.target.value='';if(!file||readOnly)return;
  if(file.size>50*1024*1024){toast('Choose an audio file smaller than 50 MB.');return;}
  toast('Reading your music…');pause();
  const uploadProjectId=project.id,token=++audioLoadToken;
  try{await probeAudio(file);const buffer=await getAudioContext().decodeAudioData(await file.arrayBuffer());if(buffer.duration>900)throw new Error('too long');if(project.id!==uploadProjectId||token!==audioLoadToken)return;remember();audioBuffer=buffer;computeWave(buffer);project.audioName=file.name;project.duration=Math.max(project.duration,Math.ceil(buffer.duration));time=0;active=project.formations[0].id;try{await putAudio(file,uploadProjectId);persistedAudio=true;toast('Music uploaded and saved on this device.');}catch{toast('Music loaded for this session. Browser storage is unavailable.');}save();render();}catch{toast('Choose a supported MP3, WAV, or M4A no longer than 15 minutes.');}
});
function probeAudio(file){return new Promise((resolve,reject)=>{let finished=false;const audio=new Audio(),url=URL.createObjectURL(file);const timeout=setTimeout(()=>finish(false),15000);const finish=ok=>{if(finished)return;finished=true;clearTimeout(timeout);audio.onerror=null;audio.onloadedmetadata=null;audio.removeAttribute('src');audio.load();URL.revokeObjectURL(url);ok?resolve():reject(Error('Unsupported audio'));};audio.preload='metadata';audio.onloadedmetadata=()=>finish(Number.isFinite(audio.duration)&&audio.duration>0&&audio.duration<=900);audio.onerror=()=>finish(false);audio.src=url;});}
$('#backup-input').addEventListener('change',async e=>{
  const file=e.target.files[0];e.target.value='';if(!file||readOnly)return;
  try{const result=await unpackBackup(file,validateProject),p=result.project;p.id=uid();p.name+=' — restored';projects.unshift(p);await switchProject(p.id);if(result.audio){await putAudio(result.audio);await loadAudio();}save();closeDialog();render();toast(result.audio?'Project and music restored.':'Project restored. Music was not included in this backup.');}catch(err){toast(err.message||'Could not read this project backup.');}
});

function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportSVG(f){return formationSVG(project,f);}

async function exportPNG(){try{const svg=exportSVG(form());const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=document.createElement('canvas');canvas.width=2400;canvas.height=1760;canvas.getContext('2d').drawImage(img,0,0,2400,1760);URL.revokeObjectURL(url);canvas.toBlob(blob=>{if(blob){download(blob,`${form().name}.png`,'image/png');closeDialog();toast('Formation image exported.');}},'image/png');}catch{toast('Image export failed. Try the SVG stage plot instead.');}}
function printSheets(){
  const win=window.open('','_blank');if(!win){toast('Allow the print window, then try again.');return;}
  win.document.write(`<!doctype html><html><head><title>${esc(project.name)} — CHORYN rehearsal sheets</title><style>body{font:12px Arial;color:#272330;margin:30px}h1{font-size:24px}h2{font-size:19px}p{white-space:pre-line}section{break-after:page}svg{width:100%;max-height:480px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:5px 8px;border-bottom:1px solid #ddd}header{display:flex;justify-content:space-between}.notes{color:#665e73}button{padding:10px 20px;margin-bottom:20px}@media print{button{display:none}body{margin:0}section:last-child{break-after:auto}}@page{size:A4 portrait;margin:14mm}</style></head><body><button onclick="window.print()">Print / Save as PDF</button>${project.formations.map((f,i)=>`<section><header><h1>CHORYN / ${esc(project.name)}</h1><p>${i+1} / ${project.formations.length}</p></header>${exportSVG(f)}<h2>${esc(f.name)} · ${timecode(f.time)}</h2><p class="notes">${esc(f.notes)}</p><table><thead><tr><th>#</th><th>Performer</th><th>Group</th><th>X (m)</th><th>Z (m)</th><th>Facing</th></tr></thead><tbody>${f.positions.map(p=>{const perf=project.performers.find(q=>q.id===p.performerId);return `<tr><td>${perf.number}</td><td>${esc(perf.name)}</td><td>${esc(perf.group)}</td><td>${shortNum(p.x)}</td><td>${shortNum(p.z)}</td><td>${p.facing}°</td></tr>`;}).join('')}</tbody></table>${i===0?`<h3>Project notes</h3><p class="notes">${esc(project.notes)}</p>`:''}</section>`).join('')}</body></html>`);win.document.close();closeDialog();
}

$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
window.addEventListener('pagehide',persistNow);
window.addEventListener('storage',event=>{if(event.key===storageKey&&event.newValue!==lastStorageRaw){storageConflict=true;saveState='blocked';updateSaveStatus();}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#rehearsal='))location.reload();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persistNow();});
setupPower({project:()=>project,readOnly:()=>readOnly,time:()=>time,formation:form,selected:()=>selected,render,pause,seek,dialog:openDialog,close:closeDialog,toast,download,selectFormation,
  replace:(next,message,options={})=>{if(readOnly)return;const valid=validateProject(next);pause();remember();project=valid;if(options.formationId&&project.formations.some(f=>f.id===options.formationId))active=options.formationId;if(!project.formations.some(f=>f.id===active))active=project.formations[0].id;time=clamp(options.time??time,0,project.duration);if(loopRegion){loopRegion.end=Math.min(loopRegion.end,project.duration);if(loopRegion.start>=loopRegion.end){loopRegion=null;loop=false;}}commit(message);},
  setTimelineExpanded:value=>{timelineExpanded=value;},
  details:(kind,id)=>{if(kind==='formation'){selectFormation(id);propertiesDialog();}else if(kind==='movement')editMovement(id);else cueDialog(project.cues.find(c=>c.id===id));},
  duplicate:()=>{$('[data-action="inspector-menu"]')?.click();$('[data-action="duplicate-formation"]')?.click();},
  setLoop:(start,end)=>{pause();loop=true;loopRegion={start,end};time=start;render();toast('Rehearsal loop ready. Press play.');},clearLoop:()=>{loop=false;loopRegion=null;render();},
  audio:async()=>{if(project.audioName&&!audioBuffer)throw Error('The uploaded music is unavailable here. Restore a portable backup or disable music.');if(!audioBuffer){audioBuffer=demoAudio();computeWave(audioBuffer);}return audioBuffer;}
});
setupFeatures({project:()=>project,readOnly:()=>readOnly,time:()=>time,formation:form,selected:()=>selected,remember,commit,render,dialog:openDialog,close:closeDialog,toast,mode:setMode,download,cueDialog,loop:(start,end)=>{pause();loop=true;loopRegion={start,end};time=start;render();play();},seek:t=>{seek(t);render();},selectFormation:id=>{mode='formation';selectFormation(id);},selectPerformer:id=>{mode='formation';selected=new Set([id]);render();}});
render();
setupPWA(updatePWAIndicators);
loadAudio().then(()=>{if(project.audioName)render();});
if(!readOnly&&!storageError)save();
if(storageError)setTimeout(()=>toast('Browser storage could not be read. Export a backup to keep this session.'),800);
